import {chromium,expect} from '@playwright/test';import {readFile,writeFile,mkdir}from'node:fs/promises';
const rec=JSON.parse(await readFile('.local/step07-review/evidence/browser/evidence.json','utf8')),base='http://127.0.0.1:4383',out='.local/step07-review/evidence/late-mutation-v2';await mkdir(out,{recursive:true});const browser=await chromium.launch({headless:true}),context=await browser.newContext({viewport:{width:1280,height:960}});await context.tracing.start({screenshots:true,snapshots:true,sources:true});const page=await context.newPage(),log={network:[],console:[],pageErrors:[],delayMs:1300,operation:'actual legal PNG upload response delayed; switch project while request pending'};page.on('request',r=>{if(r.url().includes('/api/'))log.network.push({event:'request',url:r.url(),method:r.method(),time:Date.now()})});page.on('response',r=>{if(r.url().includes('/api/'))log.network.push({event:'response',url:r.url(),status:r.status(),time:Date.now()})});page.on('pageerror',e=>log.pageErrors.push(e.message));page.on('console',m=>log.console.push({type:m.type(),text:m.text()}));
try{
 const projects=(await(await fetch(base+'/api/projects')).json()).projects,origin=projects.find(p=>p.id===rec.projectId),destination=projects.find(p=>p.id!==rec.projectId&&p.name.startsWith('R2慢轮询'));expect(destination).toBeTruthy();log.origin=origin;log.destination=destination;const read=async id=>(await(await fetch(base+'/api/projects/'+id+'/studio')).json());log.destinationBefore=await read(destination.id);await page.goto(base);await page.getByRole('button',{name:origin.name,exact:true}).click();await expect(page.getByRole('heading',{name:origin.name+' · 创作素材',exact:true})).toBeVisible();await expect(page.getByRole('button',{name:'构建当前配套',exact:true})).toBeEnabled({timeout:30000});await expect.poll(()=>page.getByAltText('当前配方处理水面').evaluate(i=>i.naturalWidth)).toBe(96);await expect(page.getByLabel('上传草地',{exact:true})).toBeEnabled();
 const pattern='**/api/projects/'+origin.id+'/sources/grass/upload?density=2';let enteredResolve;const entered=new Promise(r=>enteredResolve=r);await page.route(pattern,async route=>{enteredResolve();const response=await route.fetch();log.savedReply={status:response.status(),json:await response.json()};await new Promise(r=>setTimeout(r,1300));await route.fulfill({response})});const response=page.waitForResponse(r=>r.url().includes('/sources/grass/upload'));await page.getByLabel('上传草地',{exact:true}).setInputFiles({name:'legal-manual-grass.png',mimeType:'image/png',buffer:await readFile('.local/step07-review/evidence/browser/input-0.png')});await entered;await page.getByRole('button',{name:destination.name,exact:true}).click();await expect(page.getByRole('heading',{name:destination.name+' · 创作素材',exact:true})).toBeVisible();const selection=page.locator('.components select').nth(0);log.destinationSelectionBeforeLate=await selection.inputValue();expect(log.destinationSelectionBeforeLate).not.toBe('');const actualResponse=await response;expect(actualResponse.status()).toBe(201);await page.waitForTimeout(100);log.destinationSelectionAfterLate=await selection.inputValue();log.destinationAfter=await read(destination.id);log.currentProject=await page.evaluate(()=>localStorage.getItem('studio-project'));log.notice=await page.locator('.notice').textContent().catch(()=>null);log.grassImages=await page.getByAltText('草地原始 PNG',{exact:true}).count();await page.screenshot({path:out+'/late-upload-clears-new-project.png',fullPage:true});expect(log.destinationAfter).toEqual(log.destinationBefore);expect(log.currentProject).toBe(destination.id);log.result=log.destinationSelectionAfterLate===''?'LATE_OLD_MUTATION_CLEARS_NEW_SELECTION_REPRODUCED':'NO_ROLLBACK_OBSERVED';expect(log.pageErrors).toEqual([]);
}catch(e){log.result='PROBE_FAILURE';log.failure=String(e);await page.screenshot({path:out+'/failure.png',fullPage:true}).catch(()=>{});throw e}finally{await page.unrouteAll({behavior:'ignoreErrors'});await writeFile(out+'/evidence.json',JSON.stringify(log,null,2)+'\n');await context.tracing.stop({path:'.local/step07-review/private/late-mutation-trace.zip'});await browser.close()}
console.log(log.result,log.destinationSelectionBeforeLate,log.destinationSelectionAfterLate);
